#ifndef COD1_ACTOR_UNMOUNTED_TREE14_H
#define COD1_ACTOR_UNMOUNTED_TREE14_H
#include "cod1_actor_unmounted_tree14_defs.h"
#include "cod1_actor_look_bank14.h"
#include "cod1_actor_sparse_tree14.h"
#include "cod1_actor_dobj_pose14.h"
typedef struct {c1al14Bank_t look;c1ar14Root_t*root[2];c1ab14Clip_t*body[2];} c1aut14Bank_t;
static void C1AUT14_Free(c1aut14Bank_t*b){unsigned i;if(!b)return;C1AL14_Free(&b->look);for(i=0;i<2;i++){C1AR14_Free(b->root[i]);C1AB14_Free(b->body[i]);b->root[i]=NULL;b->body[i]=NULL;}}
static int C1AUT14_ValidShuffle(const c1ar14Root_t*r,const c1ab14Clip_t*c){return r&&c&&r->magic==C1AR14_MAGIC&&c->magic==C1AB14_MAGIC&&r->noteCount==0&&r->frames==25&&c->frames==25&&r->bones==55&&c->bones==55&&r->flags==3&&c->flags==3&&r->fps==30&&c->fps==30&&r->intervals==25&&c->intervals==25;}
static int C1AUT14_Ready(const c1aut14Bank_t*b){return b&&C1AL14_Ready(&b->look)&&C1AUT14_ValidShuffle(b->root[0],b->body[0])&&C1AUT14_ValidShuffle(b->root[1],b->body[1]);}
static int C1AUT14_Add(c1aut14Bank_t*b,unsigned i,const void*raw,size_t size){c1ar14Root_t*r=NULL;c1ab14Clip_t*c=NULL;if(!b||i>=42||!raw||!size||C1AB14_Overlap(b,sizeof(*b),raw,size))return 0;if(i>=2)return C1AL14_Add(&b->look,i-2,raw,size);if(b->root[i]||b->body[i])return 0;if(!C1AR14_Decode(raw,size,&r)||!C1AB14_Decode(raw,size,&c)||!C1AUT14_ValidShuffle(r,c)){C1AR14_Free(r);C1AB14_Free(c);return 0;}b->root[i]=r;b->body[i]=c;return 1;}
static int C1AUT14_Nodes(const float current[98],const float phases[2][21],c1ast14Node_t out[50]){c1ast14Node_t staged[50];unsigned i,g;if(!current||!phases||!out||C1AB14_Overlap(current,98*4,out,sizeof(staged))||C1AB14_Overlap(phases,42*4,out,sizeof(staged))||C1AB14_Overlap(c1aut14Definitions,sizeof(c1aut14Definitions),out,sizeof(staged)))return 0;for(i=0;i<98;i++)if(!(current[i]>=0&&current[i]<=1)||(i>=50&&current[i]!=0))return 0;if(current[0]!=1)return 0;for(g=0;g<2;g++)for(i=0;i<21;i++)if(!(phases[g][i]>=0&&phases[g][i]<=1)||((g||i>=2)&&phases[g][i]!=0))return 0;for(i=0;i<50;i++){const c1aut14Definition_t*d=c1aut14Definitions+i;staged[i].ordinal=d->ordinal;staged[i].parent=d->parent;staged[i].leaf=d->leaf;staged[i].currentWeight=current[i];staged[i].phase=d->leaf>=0&&d->leaf<2?phases[0][d->leaf]:0;}memcpy(out,staged,sizeof(staged));return 1;}
static int C1AUT14_Bank(const c1ad14Resource_t*r,const c1aut14Bank_t*b,c1ast14Bank_t*out){c1ast14Bank_t staged;unsigned i;if(!r||!r->assembly||!b||!out||!C1AUT14_Ready(b)||C1AB14_Overlap(r,sizeof(*r),out,sizeof(*out))||C1AB14_Overlap(b,sizeof(*b),out,sizeof(*out))||C1AB14_Overlap(r->assembly,sizeof(*r->assembly),out,sizeof(*out)))return 0;for(i=0;i<r->assembly->count;i++)if(r->raw[i]&&C1AB14_Overlap(r->raw[i],sizeof(*r->raw[i]),out,sizeof(*out)))return 0;memset(&staged,0,sizeof(staged));staged.bones=r->assembly->topology.boneCount;staged.count=42;for(i=0;i<42;i++){staged.clip[i]=i<2?b->body[i]:b->look.body[i-2];if(C1AB14_Overlap(staged.clip[i],sizeof(*staged.clip[i]),out,sizeof(*out)))return 0;{unsigned k;const c1ab14Clip_t*c=staged.clip[i];for(k=0;k<c->bones;k++){const c1ab14Bone_t*v=c->bone+k;if(C1AB14_Overlap(v->qi,v->nq*2,out,sizeof(*out))||C1AB14_Overlap(v->q,v->nq*8,out,sizeof(*out))||C1AB14_Overlap(v->ti,v->nt*2,out,sizeof(*out))||C1AB14_Overlap(v->t,v->nt*12,out,sizeof(*out)))return 0;}}if(!C1AD14_Map(r,staged.clip[i],staged.map[i]))return 0;}*out=staged;return 1;}
#endif
